log.raw:
{
  "critique": [
    {
      "design": "r0A",
      "good": "The full key column anchors each row, and English fits entirely within the initial viewport. Natural wrapping keeps the table relatively compact without splitting words.",
      "problems": "Only the key and English columns are visible initially, so comparing translations requires substantial sideways scrolling. The uneven row heights also make some short entries feel surrounded by excess space.",
      "cause": "The 227px key and 132px English columns consume the full viewport. The 115px Chinese, 150px Japanese and 125px Arabic columns make the table 750px wide; wrapped translations determine the taller rows."
    },
    {
      "design": "r0B",
      "good": "Every entry stays on one line, giving the rows a consistent, compact rhythm and preserving identifiers and words.",
      "problems": "The table is very wide, and even English is cut off at the initial viewport edge. Comparing a key with the later languages requires a long scroll, making it difficult to retain the row connection.",
      "cause": "The columns are sized for their longest one-line contents: 227px for keys, 217px for English and up to 304px for Japanese. Their combined width is 1162px."
    },
    {
      "design": "r0C",
      "good": "All five languages and the key are visible together, so the parallel columns and row relationships can be seen without scrolling.",
      "problems": "Identifiers and several English and Arabic words break across lines, making them hard to recognize. The English header splits, and the very tall rows interrupt scanning and create uneven blocks of white space.",
      "cause": "The 94px key column leaves only 73px for identifiers, while the 70px English and Arabic columns leave 49px for text. The 54px Chinese and 71px Japanese columns also force frequent wrapping, producing rows up to 176px tall."
    }
  ],
  "done": false,
  "designs": [
    {
      "name": "compact-scroll",
      "widths": [227, 132, 90, 120, 110],
      "change": "Keep the intact key and fully visible English column from r0A, while narrowing the three later language columns to reduce the scrolling distance. Chinese and Japanese can wrap naturally; Arabic retains room for its longest word."
    },
    {
      "name": "balanced-scroll",
      "widths": [227, 150, 105, 135, 120],
      "change": "Give English and the translation columns more breathing room than the compact option, seeking shorter rows while retaining intact keys. The initial viewport shows most of English, with a moderate scrolling cost."
    },
    {
      "name": "shared-viewport",
      "widths": [160, 100, 65, 80, 80],
      "change": "Test a narrower key and language columns so the initial viewport reaches into Chinese and the full table requires less scrolling. This accepts some identifier splitting to show more of the language comparison at once."
    }
  ]
}
